    41  void Packet::setRawPacket(RawPacket* rawPacket, bool freeRawPacket, ProtocolType parseUntil, OsiModelLayer parseUntilLayer)
    42  {
    43          destructPacketData();
    44
    45          m_FirstLayer = NULL;
    46          m_LastLayer = NULL;
    47          m_ProtocolTypes = UnknownProtocol;
    48          m_MaxPacketLen = rawPacket->getRawDataLen();
    49          m_FreeRawPacket = freeRawPacket;
    50          m_RawPacket = rawPacket;
    51          if (m_RawPacket == NULL)
    52                  return;
    53
    54          LinkLayerType linkType = m_RawPacket->getLinkLayerType();
    55
    56          m_FirstLayer = createFirstLayer(linkType);
    57
    58          m_LastLayer = m_FirstLayer;
    59          Layer* curLayer = m_FirstLayer;
    60          while (curLayer != NULL && (curLayer->getProtocol() & parseUntil) == 0 && curLayer->getOsiModelLayer() <= parseUntilLayer)
    61          {
    62                  m_ProtocolTypes |= curLayer->getProtocol();
    63                  curLayer->parseNextLayer();
    64                  curLayer->m_IsAllocatedInPacket = true;
    65                  curLayer = curLayer->getNextLayer();
    66                  if (curLayer != NULL)
    67                          m_LastLayer = curLayer;
    68          }
    69
    70          if (curLayer != NULL && (curLayer->getProtocol() & parseUntil) != 0)
    71          {
    72                  m_ProtocolTypes |= curLayer->getProtocol();
    73                  curLayer->m_IsAllocatedInPacket = true;
    74          }
    75
    76          if (curLayer != NULL &&  curLayer->getOsiModelLayer() > parseUntilLayer)
    77          {
    78                  m_LastLayer = curLayer->getPrevLayer();
    79                  delete curLayer;
    80                  m_LastLayer->m_NextLayer = NULL;
    81          }
    82
    83          if (parseUntil == UnknownProtocol && parseUntilLayer == OsiModelLayerUnknown)
    84          {
    85                  // find if there is data left in the raw packet that doesn't belong to any layer. In that case it's probably a packet trailer.
    86                  // create a PacketTrailerLayer layer and add it at the end of the packet
    87                  int trailerLen = (int)((m_RawPacket->getRawData() + m_RawPacket->getRawDataLen()) - (m_LastLayer->getData() + m_LastLayer->getDataLen()));
    88                  if (trailerLen > 0)
    89                  {
    90                          PacketTrailerLayer* trailerLayer = new PacketTrailerLayer(
    91                                          (uint8_t*)(m_LastLayer->getData() + m_LastLayer->getDataLen()),
    92                                          trailerLen,
    93                                          m_LastLayer,
    94                                          this);
    95
    96                          trailerLayer->m_IsAllocatedInPacket = true;
    97                          m_LastLayer->setNextLayer(trailerLayer);
    98                          m_LastLayer = trailerLayer;
    99                          m_ProtocolTypes |= trailerLayer->getProtocol();
   100                  }
   101          }
   102  }
