   128  void Packet::destructPacketData()
   129  {
   130          Layer* curLayer = m_FirstLayer;
   131          while (curLayer != NULL)
   132          {
   133                  Layer* nextLayer = curLayer->getNextLayer();
   134                  if (curLayer->m_IsAllocatedInPacket)
   135                          delete curLayer;
   136                  curLayer = nextLayer;
   137          }
   138
   139          if (m_RawPacket != NULL && m_FreeRawPacket)
   140          {
   141                  delete m_RawPacket;
   142          }
   143  }
