   173  void Packet::reallocateRawData(size_t newSize)
   174  {
   175          LOG_DEBUG("Allocating packet to new size: %d", (int)newSize);
   176
   177          // allocate a new array with size newSize
   178          m_MaxPacketLen = newSize;
   179
   180          // set the new array to RawPacket
   181          if (!m_RawPacket->reallocateData(m_MaxPacketLen))
   182          {
   183                  LOG_ERROR("Couldn't reallocate data of raw packet to %d bytes", (int)m_MaxPacketLen);
   184                  return;
   185          }
   186
   187          // set all data pointers in layers to the new array address
   188          const uint8_t* dataPtr = m_RawPacket->getRawData();
   189
   190          Layer* curLayer = m_FirstLayer;
   191          while (curLayer != NULL)
   192          {
   193                  LOG_DEBUG("Setting new data pointer to layer '%s'", typeid(curLayer).name());
   194                  curLayer->m_Data = (uint8_t*)dataPtr;
   195                  dataPtr += curLayer->getHeaderLen();
   196                  curLayer = curLayer->getNextLayer();
   197          }
   198  }
